#!/usr/bin/env node
// Copies the Sentinel Hub's dashboard rendering code and styles into this site,
// so the public Control Center draws the same gauges, cards and charts as the hub.
//
// Usage (from this repo):
//   node tools/sync-hub-dashboard.cjs /path/to/ReCore/sentinel/firmware/sentinel-hub/src/web_server.cpp
//
// Writes (do not edit by hand; re-run after hub UI changes):
//   js/hub-dashboard-core.js   hub functions + constants, verbatim
//   css/hub-dashboard.css      hub styles, scoped under .hubDash
//
// js/sentinel-dashboard.js (hand-written) adapts cloud data to the hub's format
// and overrides the few hub functions that talk to the hub itself.
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const src = process.argv[2];
if (!src) { console.error('Usage: node tools/sync-hub-dashboard.cjs <path to web_server.cpp>'); process.exit(1); }
const cpp = fs.readFileSync(src, 'utf8');
const html = (cpp.match(/R"rawliteral\(([\s\S]*?)\)rawliteral"/) || [])[1];
if (!html) throw new Error('Hub page (INDEX_HTML raw literal) not found in ' + src);
const js = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]).join('\n');
const css = [...html.matchAll(/<style>([\s\S]*?)<\/style>/g)].map(m => m[1]).join('\n');

const FUNCTIONS = `esc cardClass badge signalQuality fmtRatio dividerText statBlock paddedRange chartXY historySvg
  chartSelect chartHover chartClear chartKey historyMeta dashboardCard estimateSoc gaugePt gaugeArc gaugeSvg
  signalBars upText ageText toggleDial dialKey voltTrend trendChip miniCard renderMiniCards renderDashboardCards
  selectDashboardNode rememberChartInspection restoreChartInspection cToF mapRecent mapHourly refreshAges
  chartData chartCount rangeName rangePicker renderRangePickers setChartRange emptyHistoryText fmtHour hourlyTip
  axisLeft axisRight voltBand`.split(/\s+/).filter(Boolean);
const CONSTANTS = 'GAUGE_PROFILES SOC_TABLE BOLT_ICON THERMO_ICON STATUS_CODES RANGE_HOURS RANGE_LABELS'.split(' ');

// Run the hub script against inert stand-ins, then read definitions back out.
// Function.prototype.toString returns each function's exact source text.
const element = new Proxy(function () {}, {
  get: (t, k) => k === Symbol.toPrimitive ? () => '' : (k === 'length' ? 0 : element),
  apply: () => element, construct: () => element, set: () => true,
});
const sandbox = {
  document: element, window: element, navigator: element, L: element, location: element,
  localStorage: { getItem: () => null, setItem() {} }, fetch: () => new Promise(() => {}),
  setInterval() {}, setTimeout() {}, clearTimeout() {}, console,
};
vm.createContext(sandbox);
try { vm.runInContext(js, sandbox, { filename: 'hub-dashboard.js' }); } catch { /* top-level page setup; definitions are already in place */ }
const out = [];
const lexical = new vm.Script(`({${CONSTANTS.join(',')}})`).runInContext(sandbox);
for (const name of CONSTANTS) out.push(`const ${name}=${JSON.stringify(lexical[name])};`);
for (const name of FUNCTIONS) {
  const fn = new vm.Script(name).runInContext(sandbox);
  if (typeof fn !== 'function') throw new Error('Hub function missing: ' + name);
  out.push(fn.toString());
}

const header = `// GENERATED by tools/sync-hub-dashboard.cjs from the Sentinel Hub firmware
// (sentinel/firmware/sentinel-hub/src/web_server.cpp). Do not edit by hand.
`;
const state = `// Page state the hub functions expect.
let latestNodes=[];let selectedDashboardNode=null;const histories={};let dialModes={};
try{dialModes=JSON.parse(localStorage.getItem('sentinelDialModes')||'{}')||{}}catch(e){}
let chartRange='recent';const rangeHist={'24h':{},'7d':{},'30d':{}};
let histRev={},rangeRev={},rangeAt={},rangeAvail=true;`;
// Frozen copies of the hub's originals, for pages that wrap one of them.
const originals = `const HUB=Object.freeze({${FUNCTIONS.join(',')}});`;
fs.writeFileSync(path.join(__dirname, '../js/hub-dashboard-core.js'), header + state + '\n' + out.join('\n') + '\n' + originals + '\n');

// Scope every rule under .hubDash so hub styles don't leak into the rest of the site.
function scope(block) {
  let res = '', i = 0;
  while (i < block.length) {
    const open = block.indexOf('{', i);
    if (open < 0) break;
    const head = block.slice(i, open).trim();
    let depth = 1, j = open + 1;
    while (depth && j < block.length) { if (block[j] === '{') depth++; else if (block[j] === '}') depth--; j++; }
    const body = block.slice(open + 1, j - 1);
    if (head.startsWith('@media') || head.startsWith('@supports')) res += `${head}{${scope(body)}}\n`;
    else if (head.startsWith('@')) res += `${head}{${body}}\n`;
    else {
      const sel = head.split(',').map(s => s.trim()).filter(Boolean).map(s => {
        if (s === ':root' || s === 'html' || s === 'body') return '.hubDash';
        if (s === '*') return '.hubDash *';
        return '.hubDash ' + s.replace(/^(html|body)\s+/, '');
      }).join(',');
      res += `${sel}{${body}}\n`;
    }
    i = j;
  }
  return res;
}
const cssHeader = '/* GENERATED by tools/sync-hub-dashboard.cjs from the Sentinel Hub firmware. Do not edit by hand. */\n';
fs.writeFileSync(path.join(__dirname, '../css/hub-dashboard.css'), cssHeader + scope(css.replace(/\/\*[\s\S]*?\*\//g, '')));
console.log(`Synced ${FUNCTIONS.length} functions, ${CONSTANTS.length} constants, ${css.length} bytes of CSS.`);
